-- Módulo 50: seguimiento manual; los importes reconocidos no acreditan pagos.
CREATE TABLE "SiniestrosFlota" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Codigo" varchar(20) NOT NULL CHECK ("Codigo" = btrim("Codigo") AND length("Codigo") > 0),
    "Placa" varchar(20) NOT NULL CHECK ("Placa" = upper(btrim("Placa")) AND length("Placa") > 0),
    "Lugar" varchar(200) NOT NULL CHECK ("Lugar" = btrim("Lugar") AND length("Lugar") > 0),
    "Descripcion" varchar(500) NOT NULL CHECK ("Descripcion" = btrim("Descripcion") AND length("Descripcion") > 0),
    "Tipo" varchar(20) NOT NULL CHECK ("Tipo" IN ('Accidente','Robo','DanoMaterial')),
    "FechaIncidente" timestamptz NOT NULL,
    "Observaciones" varchar(500),
    "Estado" varchar(15) NOT NULL DEFAULT 'Registrado',
    "NumeroPoliza" varchar(40),
    "Aseguradora" varchar(150),
    "NumeroReclamo" varchar(40),
    "Moneda" varchar(3) CHECK ("Moneda" ~ '^[A-Z]{3}$'),
    "MontoReclamado" numeric(12,2) CHECK ("MontoReclamado" BETWEEN 0.01 AND 9999999999.99),
    "FechaReclamo" timestamptz,
    "Resultado" varchar(15),
    "MontoReconocido" numeric(12,2) CHECK ("MontoReconocido" BETWEEN 0 AND 9999999999.99 AND "MontoReconocido" <= "MontoReclamado"),
    "Resolucion" varchar(500),
    "FechaCierre" timestamptz,
    "MotivoAnulacion" varchar(500),
    "FechaAnulacion" timestamptz,
    CONSTRAINT "CK_SiniestrosFlota_Reclamo" CHECK (
       ("FechaReclamo" IS NULL AND "NumeroPoliza" IS NULL AND "Aseguradora" IS NULL AND "NumeroReclamo" IS NULL AND "Moneda" IS NULL AND "MontoReclamado" IS NULL) OR
       ("FechaReclamo" IS NOT NULL AND length(btrim(coalesce("NumeroPoliza",''))) > 0 AND length(btrim(coalesce("Aseguradora",''))) > 0 AND length(btrim(coalesce("NumeroReclamo",''))) > 0 AND "Moneda" IS NOT NULL AND "MontoReclamado" IS NOT NULL)),
    CONSTRAINT "CK_SiniestrosFlota_Cierre" CHECK (
       ("FechaCierre" IS NULL AND "Resultado" IS NULL AND "MontoReconocido" IS NULL AND "Resolucion" IS NULL) OR
       ("FechaCierre" IS NOT NULL AND "FechaReclamo" IS NOT NULL AND "Resultado" IS NOT NULL AND "MontoReconocido" IS NOT NULL AND length(btrim(coalesce("Resolucion",''))) > 0 AND (("Resultado" = 'Aceptado' AND "MontoReconocido" > 0) OR ("Resultado" = 'Rechazado' AND "MontoReconocido" = 0)))),
    CONSTRAINT "CK_SiniestrosFlota_Estado" CHECK (
       ("Estado" = 'Registrado' AND "FechaReclamo" IS NULL AND "FechaCierre" IS NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
       ("Estado" = 'EnReclamo' AND "FechaReclamo" IS NOT NULL AND "FechaCierre" IS NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
       ("Estado" = 'Cerrado' AND "FechaCierre" IS NOT NULL AND "FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL) OR
       ("Estado" = 'Anulado' AND "FechaCierre" IS NULL AND "FechaAnulacion" IS NOT NULL AND length(btrim(coalesce("MotivoAnulacion",''))) > 0))
);
CREATE UNIQUE INDEX "IX_SiniestrosFlota_Codigo" ON "SiniestrosFlota" (lower(btrim("Codigo")));
